<?php require_once '../../config/bootstrap.php'; requireLogin('../auth/login.php'); require_once '../../repositories/book-repository.php'; $search=trim($_GET['search']??'');$cat=(int)($_GET['category']??0);$books=getBooks($search,$cat);$categories=db()['categories'];$base='../../';$pageTitle='Manajemen Buku';$pageSubtitle='Kelola data buku, kategori, dan penulis'; ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=$pageTitle?></title><link rel="stylesheet" href="../../styles/books/index.css"></head><body><div class="app-shell"><?php require '../../components/admin/sidebar.php'; ?><main class="app-main"><?php require '../../components/admin/topbar.php'; ?><div class="app-content"><div class="toolbar"><form method="GET" action="index.php" class="toolbar-filters"><input name="search" value="<?=e($search)?>" class="search-input" placeholder="Cari judul buku..."><select name="category" class="filter-select"><option value="">Semua Kategori</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$cat===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><button class="btn btn-outline btn-sm">Cari</button></form><a href="create.php" class="btn btn-primary">+ Tambah Buku</a></div><div class="data-card"><table class="data-table"><thead><tr><th>Judul</th><th>Kategori</th><th>Penulis</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php foreach($books as $b):?><tr><td><a href="show.php?id=<?=$b['id']?>"><?=e($b['title'])?></a><br><small><?=e($b['isbn'])?> · <?=e($b['year'])?></small></td><td><?=e($b['category'])?></td><td><?=e(implode(', ',$b['authors']))?></td><td><?=e($b['stock'])?></td><td><a href="edit.php?id=<?=$b['id']?>" class="btn btn-outline btn-sm">Edit</a> <a onclick="return confirm('Hapus buku ini?')" href="../../actions/books/destroy.php?id=<?=$b['id']?>" class="btn btn-danger btn-sm">Hapus</a></td></tr><?php endforeach; if(!$books):?><tr><td colspan="5">Data buku tidak ditemukan.</td></tr><?php endif;?></tbody></table></div></div></main></div></body></html>
